			move.l (a0)+, (a1)+
			clr.b var_longest_longest
			clr.w var_longest_k
			move.l sp, p_longest_rs
			lea p_longest, sp
			rts
p_longest_r:		; end of longest
			movea.l p_longest_rs, sp
			rts
p_shout_c:		; call shout
			movea.l (sp)+, a0		; s() descriptor
			lea pa_shout_s, a1
			move.l (a0)+, (a1)+
			move.l (a0)+, (a1)+
			move.l (a0)+, (a1)+
			clr.w var_shout_k
			move.l sp, p_shout_rs
			lea p_shout, sp
			rts
p_shout_r:		; end of shout
			movea.l p_shout_rs, sp
			rts
p_bigsum_c:		; call bigsum
			movea.l (sp)+, a0		; v() descriptor
			lea pa_bigsum_v, a1
			move.l (a0)+, (a1)+
			move.l (a0)+, (a1)+
			move.l (a0)+, (a1)+
			clr.l var_bigsum_bigsum
			clr.w var_bigsum_k
			move.l sp, p_bigsum_rs
			lea p_bigsum, sp
			rts
p_bigsum_r:		; end of bigsum
			movea.l p_bigsum_rs, sp
			rts

