;## kw_aset
;kw_aset, <arraybase>, <indexvar>, <sourcevar>
kw_aset:
			movea.l (sp)+, a0
			movea.l (sp)+, a1
			move.w (a1), d0
			ext.l d0
			add.l d0, d0
			movea.l (sp)+, a1
			move.w (a1), 0(a0, d0.l)
			rts

			even
;## kw_strcpy
;kw_strcpy, <destaddr>, <srcaddr>  - cut at the destination's capacity byte
kw_strcpy:
			movea.l (sp)+, a1
			movea.l (sp)+, a0
			moveq #0, d1
			move.b -1(a1), d1
ntc_strcpy_lp:					; a0 -> a1, at most d1 chars (d1.w > 0), then the 0
			subq.w #1, d1
			bmi ntc_strcpy_cut
ntc_strcpy_l2:
			move.b (a0)+, (a1)+
			dbeq d1, ntc_strcpy_l2
			beq ntc_strcpy_e
ntc_strcpy_cut:
			clr.b (a1)
ntc_strcpy_e:
			rts

			even
;## kw_strcpyn kw_strcpy
;kw_strcpyn, <destaddr>, <srcaddr>, <capacity>  - into an array element (no capacity byte)
kw_strcpyn:
			movea.l (sp)+, a1
			movea.l (sp)+, a0
			move.l (sp)+, d1
			andi.w #$FF, d1
			bra ntc_strcpy_lp

			even
;## kw_strlen
;kw_strlen, <straddr>, <destvar>
kw_strlen:
			movea.l (sp)+, a0
			moveq #-1, d0
kw_sl_lp:
			addq.w #1, d0
			tst.b (a0)+
			bne kw_sl_lp
			movea.l (sp)+, a0
			move.w d0, (a0)
			rts

			even
;## kw_strcmpeq
;kw_strcmpeq, <addr1>, <addr2>  - Z if equal
kw_strcmpeq:
			movea.l (sp)+, a0
			movea.l (sp)+, a1
kw_seq_lp:
			move.b (a0)+, d0
			cmp.b (a1)+, d0
			bne kw_seq_no
			tst.b d0
			bne kw_seq_lp
kw_seq_no:
			rts

			even
;## ntc_printbuf ntc_data ntc_plat_screen
; print the 0 terminated text at a0, then rts (thread). On the thread.
ntc_printbuf:
			NTC_RS
			movea.l a0, a2
ntc_pb_lp:
			moveq #0, d0
			move.b (a2)+, d0
			beq ntc_pb_end
			jsr ntc_plat_putc
			bra ntc_pb_lp
ntc_pb_end:
			NTC_TS
			rts

			even
;## kw_printstrvar ntc_printbuf
;kw_printstrvar, <straddr>
kw_printstrvar:
			movea.l (sp)+, a0
			bra ntc_printbuf

			even
;## ntc_itoa ntc_data
; d0.w = signed value, a1 = buffer: the digits and a 0 (a1 ends on the 0).
; jmp (a6). Uses d0-d2, a0
ntc_itoa:
			ext.l d0
			bpl ntc_ia_pos
			move.b #'-', (a1)+
			neg.l d0
ntc_ia_pos:
			lea ntc_ia_tmp+8, a0
			clr.b -(a0)
ntc_ia_lp:
			divu.w #10, d0
			swap d0
			addi.b #'0', d0
			move.b d0, -(a0)
			clr.w d0
			swap d0
			tst.w d0
			bne ntc_ia_lp
ntc_ia_cp:
			move.b (a0)+, (a1)+
			bne ntc_ia_cp
			subq.l #1, a1
			jmp (a6)

			even
;## kw_printint ntc_printbuf ntc_itoa
;kw_printint, <var>  - signed decimal
kw_printint:
			movea.l (sp)+, a0
			move.w (a0), d0
			lea ntc_numbuf, a1
			lea kw_pi_done, a6
			bra ntc_itoa
kw_pi_done:
			lea ntc_numbuf, a0
			bra ntc_printbuf

			even
;## kw_printtab ntc_data ntc_plat_screen
;kw_printtab, <nvar>  - Tab(n) in Print: spaces up to column n (1 based),
;  a new line first when the cursor is already past it. n off the line: nothing
kw_printtab:
			movea.l (sp)+, a0
			move.w (a0), d2
			subq.w #1, d2
ntc_pt_go:						; d2 = the column (0 based)
			moveq #0, d0
			move.b ntc_scols, d0
			cmp.w d0, d2
			bcc ntc_pt_end			; (also below 0: unsigned)
			NTC_RS
			moveq #0, d0
			move.b ntc_curx, d0
			cmp.w d0, d2
			bcc ntc_pt_lp
			jsr ntc_plat_newline
ntc_pt_lp:
			moveq #0, d0
			move.b ntc_curx, d0
			cmp.w d0, d2
			bls ntc_pt_done
			moveq #' ', d0
			jsr ntc_plat_putc
			bra ntc_pt_lp
ntc_pt_done:
			NTC_TS
ntc_pt_end:
			rts

			even
;## kw_printnl0 ntc_data ntc_plat_screen
;kw_printnl0  - new line unless the cursor is at the start of a line
kw_printnl0:
			tst.b ntc_curx
			beq kw_pn0_end
			NTC_RS
			jsr ntc_plat_newline
			NTC_TS
kw_pn0_end:
			rts

			even
;## kw_printnl ntc_data ntc_plat_screen
kw_printnl:
			NTC_RS
			jsr ntc_plat_newline
			NTC_TS
			rts

			even
;## kw_cls ntc_data ntc_plat_screen
kw_cls:
			NTC_RS
			jsr ntc_plat_cls
			NTC_TS
			rts

			even
;## kw_strucase
;kw_strucase, <dest>, <src>  - UCase$
kw_strucase:
			movea.l (sp)+, a1
			movea.l (sp)+, a0
kw_uc_lp:
			move.b (a0)+, d0
			cmpi.b #'a', d0
			bcs kw_uc_put
			cmpi.b #'z', d0
			bhi kw_uc_put
			subi.b #32, d0
kw_uc_put:
			move.b d0, (a1)+
			bne kw_uc_lp
			rts

			even
;## ntc_paddr
; a0 = descriptor, a1 = index var: a0 = element address, d1 = element size. jmp (a6)
ntc_paddr:
			move.w (a1), d0
			sub.w 2(a0), d0				; element number
ntc_pa_tail:					; d0.w = element number, a0 = descriptor
			move.w 10(a0), d1
			movea.w (a0), a0
			muls.w d1, d0
			adda.l d0, a0
			jmp (a6)

			even
;## kw_pget ntc_paddr
;kw_pget, <descriptor>, <indexvar>, <dest>  - dest = parameter array(index)
kw_pget:
			movea.l (sp)+, a0
			movea.l (sp)+, a1
			lea kw_pg_a, a6
			bra ntc_paddr
kw_pg_a:
			movea.l (sp)+, a1
			cmpi.w #1, d1				; a Byte element: into the Integer's low byte
			bne kw_pg_n1
			clr.b (a1)+
kw_pg_n1:
			subq.w #1, d1
kw_pg_lp:
			move.b (a0)+, (a1)+
			dbra d1, kw_pg_lp
			rts

			even
;## kw_pset ntc_paddr
;kw_pset, <descriptor>, <indexvar>, <src>  - parameter array(index) = src
kw_pset:
			movea.l (sp)+, a0
			movea.l (sp)+, a1
			lea kw_ps_a, a6
			bra ntc_paddr
kw_ps_a:
			movea.l (sp)+, a1
			cmpi.w #1, d1				; a Byte element: from the Integer's low byte
			bne kw_ps_n1
			addq.l #1, a1
kw_ps_n1:
			subq.w #1, d1
kw_ps_lp:
			move.b (a1)+, (a0)+
			dbra d1, kw_ps_lp
			rts

			even
;## kw_psets ntc_paddr kw_strcpy
;kw_psets, <descriptor>, <indexvar>, <src>  - String parameter array(index) = src
kw_psets:
			movea.l (sp)+, a0
			movea.l (sp)+, a1
			lea kw_pss_a, a6
			bra ntc_paddr
kw_pss_a:
			movea.l a0, a1
			movea.l (sp)+, a0
			subq.w #1, d1
			bra ntc_strcpy_lp

			even
;## kw_lbound
;kw_lbound, <descriptor + 2 * (dimension - 1)>, <dest>  - LBound
kw_lbound:
			movea.l (sp)+, a0
			movea.l (sp)+, a1
			move.w 2(a0), (a1)
			rts

